async function broadcastCallback(q,api,options){
  const {store,enqueueBroadcast}=options;
  if(!options.adminIds.includes(q.from.id))return api.answerCallbackQuery(q.id,'Not allowed',true);
  const parts=String(q.data||'').split(':');
  if(parts[0]!=='bc'||parts.length<4)return api.answerCallbackQuery(q.id,'Invalid broadcast action',true);
  const fromChatId=Number(parts[1]);
  const sourceMessageId=Number(parts[2]);
  const audience=parts[3];
  if(!Number.isFinite(fromChatId)||!Number.isFinite(sourceMessageId)||!['users','groups','channels','all'].includes(audience))return api.answerCallbackQuery(q.id,'Invalid broadcast data',true);
  const mode=parts[4];
  const pin=parts[5];
  const action=parts[6];
  if(parts.length===4){
    await api.answerCallbackQuery(q.id);
    return api.editMessageText(q.message.chat.id,q.message.message_id,uiText('📢 SELECT AUDIENCE'),[
      [Object.assign(uiButton('👤 USERS','primary'),{callback_data:`bc:${fromChatId}:${sourceMessageId}:users`}),Object.assign(uiButton('👥 GROUPS','primary'),{callback_data:`bc:${fromChatId}:${sourceMessageId}:groups`})],
      [Object.assign(uiButton('📢 CHANNELS','primary'),{callback_data:`bc:${fromChatId}:${sourceMessageId}:channels`}),Object.assign(uiButton('🌐 ALL','success'),{callback_data:`bc:${fromChatId}:${sourceMessageId}:all`})],
      [Object.assign(uiButton('❌ CANCEL','danger'),{callback_data:'bcx'})]
    ]);
  }
  if(!mode){
    await api.answerCallbackQuery(q.id);
    return api.editMessageText(q.message.chat.id,q.message.message_id,uiText(`📢 ${audience.toUpperCase()} SELECTED\n\nChoose delivery mode.`),[
      [Object.assign(uiButton('📤 COPY','primary'),{callback_data:`bc:${fromChatId}:${sourceMessageId}:${audience}:copy`}),Object.assign(uiButton('↪️ FORWARD','primary'),{callback_data:`bc:${fromChatId}:${sourceMessageId}:${audience}:forward`})],
      [Object.assign(uiButton('❌ CANCEL','danger'),{callback_data:'bcx'})]
    ]);
  }
  if(pin===undefined){
    await api.answerCallbackQuery(q.id);
    return api.editMessageText(q.message.chat.id,q.message.message_id,uiText(`📢 ${audience.toUpperCase()} • ${mode.toUpperCase()}\n\nChoose pin option.`),[
      [Object.assign(uiButton('📌 PIN','success'),{callback_data:`bc:${fromChatId}:${sourceMessageId}:${audience}:${mode}:1`}),Object.assign(uiButton('🚫 WITHOUT PIN','primary'),{callback_data:`bc:${fromChatId}:${sourceMessageId}:${audience}:${mode}:0`})],
      [Object.assign(uiButton('❌ CANCEL','danger'),{callback_data:'bcx'})]
    ]);
  }
  if(action!=='send'){
    await api.answerCallbackQuery(q.id);
    return api.editMessageText(q.message.chat.id,q.message.message_id,uiText(`📢 BROADCAST READY\n\n👤 Audience: ${audience.toUpperCase()}\n📤 Mode: ${mode.toUpperCase()}\n📌 Pin: ${pin==='1'?'YES':'NO'}\n\nSend this broadcast now?`),[
      [Object.assign(uiButton('🚀 SEND BROADCAST','success'),{callback_data:`bc:${fromChatId}:${sourceMessageId}:${audience}:${mode}:${pin}:send`})],
      [Object.assign(uiButton('❌ CANCEL','danger'),{callback_data:'bcx'})]
    ]);
  }
  const total=store.audienceCount?await store.audienceCount(audience):0;
  const job={audience,kinds:TARGETS[audience],fromChatId,messageId:sourceMessageId,statusChatId:q.message.chat.id,statusMessageId:q.message.message_id,afterId:Number.MIN_SAFE_INTEGER,total,sent:0,failed:0,removed:0,startedAt:Date.now(),mode,pin:pin==='1'};
  await api.answerCallbackQuery(q.id,'Broadcast queued');
  await editStatus(api,job,progressText(job));
  try{await enqueueBroadcast(job)}catch(e){await editStatus(api,job,errorText(job,e))}
}
